B.Os=new A.U(B.Pi,[B.amv,B.amh,B.ame,B.amc,B.amb,B.amO],t.dM)
B.amn=new A.W("\u0627\u0644\u0622\u064a\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0635\u062d\u0641\u060c \u0644\u0627 \u0645\u0646 \u0630\u0627\u0643\u0631\u0629 \u0627\u0644\u0646\u0645\u0648\u0630\u062c","Verses come from the Mushaf, not the model\u2019s memory")
